INSERT INTO language_levels(language_id, cefr_code) SELECT l.id, c.code FROM languages l, cefr_levels c WHERE l.code = 'bn' AND c.code IN ('A2', 'B1');
INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'yesterday', 'What I Did Yesterday', 'Talk about the past: where you went and what you did.', 'Monday morning: a colleague asks about your weekend.', 'Kolkata Bengali uses “kal” for both yesterday and tomorrow: the verb tells you which. The past ends in -lam for “I”: “gelam” (I went), “khelam” (I ate), “korlam” (I did), and in -len for the polite “you”: “korlen?” (did you do?).', 1, 'published', datetime('now'), datetime('now'), 1);
