INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'plans', 'Plans for the Weekend', 'Make plans and talk about the future.', 'Friday evening: making weekend plans with a flatmate.', 'The future ends in -bo for “I”: “jabo” (I''ll go), “uthbo” (I''ll get up), “pathabo” (I''ll send). “Let''s” is “cholo, … -i”: “cholo, metro-te jai” (let''s go by metro).', 2, 'published', datetime('now'), datetime('now'), 1);
