INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'favours', 'Asking for Favours', 'Ask politely for help and favours.', 'Asking a neighbour in your building for help.', 'To ask kindly, ask whether the person could do it: “korte parben?” (could you do?), “bolte parben?” (could you say?). “Ektu” (a little) softens anything.', 3, 'published', datetime('now'), datetime('now'), 1);
