INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'likes', 'Likes and Preferences', 'Say what you like and what you prefer.', 'Lunch with colleagues: talking about food.', 'Bengali says “to me, it feels good”: “amar … bhalo lage” (I like …), “bhalo lage na” (I don''t like). “Apnar ki bhalo lage?” asks what someone likes. In “cha na coffee?”, “na” means “or”.', 4, 'published', datetime('now'), datetime('now'), 1);
