INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'comparing', 'Comparing Things', 'Compare prices, sizes and options.', 'Choosing between two kurtas in New Market.', 'To compare, add “-er cheye” (than) to what you compare against: “bus-er cheye” (than the bus), “otar cheye” (than that one). Then say what is more: “shosta” (cheaper), “taratari” (faster), “boro” (bigger).', 5, 'published', datetime('now'), datetime('now'), 1);
