INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'B1', 'opinions', 'Giving Your Opinion', 'Say what you think, agree and disagree politely.', 'Friends arguing about the best biryani in Kolkata.', '“Amar mone hoy” (it seems to me) starts an opinion; “ami ekmot” (I agree) and “ami ekmot noi” (I don''t agree) answer one. Kolkata biryani comes with a potato, and people argue about it!', 4, 'published', datetime('now'), datetime('now'), 1);
