INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'B1', 'what-happened', 'Telling What Happened', 'Tell a story: who, when, and what someone said.', 'Telling a friend about a bad day.', '“-te bollo” reports what someone told you to do: “kal ashte bollo” (they told me to come tomorrow). “Keu” is “someone”, and a verb said twice in -te is “by the time”: “pouchhate pouchhate” (by the time I got there).', 6, 'published', datetime('now'), datetime('now'), 1);
