INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'past-tense', 1);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'past-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The past: “gelam”, “khelam”, “korlam”', 'What you did ends in -lam: “gelam” (I went), “khelam” (I ate), “korlam” (I did). With “apni” (you, polite) it ends in -len: “korlen?” (did you do?), “gelen?” (did you go?). Bengali''s past is not gendered.');
