INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'future-tense', 2);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'future-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The future: “-bo”', 'What you will do ends in -bo: “uthbo” (I''ll get up), “jabo” (I''ll go, we''ll go), “shesh korbo” (I''ll finish). “Kal” with a future verb means tomorrow; with a past verb, yesterday.');
