INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'polite-questions', 3);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'polite-questions'), (SELECT id FROM languages WHERE code = 'en'), 'Softer requests: “… -te parben?”', 'To ask kindly, ask whether the person could do it: “korte parben?” (could you do?), “bolte parben?” (could you say?), or use the polite future: “pathaben?” (will you send?), “deben?” (will you give?). It is softer than the plain request (“din”, “korun”).');
