INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'liking', 4);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'liking'), (SELECT id FROM languages WHERE code = 'en'), 'Liking things: “amar … bhalo lage”', 'Bengali says “to me, X feels good”: “amar cha bhalo lage” (I like tea), “bhalo lage na” (don''t like). “Pochhondo kori” is “I prefer, I like”. It is the same whoever is speaking.');
