INSERT INTO lesson_grammar(lesson_id, grammar_topic_id, language_id) VALUES ((SELECT id FROM lessons WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'comparing'), (SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'liking'), (SELECT id FROM languages WHERE code = 'bn'));
INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'A2', 'comparing', 5);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'comparing'), (SELECT id FROM languages WHERE code = 'en'), 'Comparing: “-er cheye”', 'Add “-er cheye” (than) to what you compare against: “bus-er cheye” (than the bus). After “eta” (this) and “ota” (that) it becomes “etar cheye” and “otar cheye”, and “er cheye” is “than this”. Then say what is more: “shosta” (cheaper), “taratari” (faster).');
