INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'B1', 'having-to', 1);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'having-to'), (SELECT id FROM languages WHERE code = 'en'), 'Having to: “-te hobe”', 'Add “-te hobe” to a verb for what you have to do: “jete hobe” (have to go), “bolte hobe” (need to speak). “Amar … dorkar” on its own means “I need …”: “amar chhuti dorkar” (I need leave). “-te chai” is “want to”: “bolte chai” (I want to speak).');
