INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'B1', 'if-and-when', 2);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'if-and-when'), (SELECT id FROM languages WHERE code = 'en'), 'If and when: “-le” and “jokhon”', '“-le” makes “if”: “brishti hole” (if it rains), “jiggesh korle” (if you ask), “pele” (if I get). “Jokhon” makes “when”: “jokhon elam” (when I came). The rest of the sentence says what happens then.');
