INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'bn'), 'B1', 'can-and-cant', 3);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'can-and-cant'), (SELECT id FROM languages WHERE code = 'en'), 'Can and can''t: “-te pari” and “-te parbo na”', '“-te pari” is “I can”: “chalate pari” (I can drive); “pari na” is “I can''t”. For one particular time use the future: “ashte parbo na” (I won''t be able to come). With “apni”: “porte paren?” (can you read?).');
