INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'bn') AND slug = 'what-someone-said'), (SELECT id FROM languages WHERE code = 'en'), 'Telling what happened: “-te bollo”, “keu” and “-te -te”', '“-te bollo” reports what someone told you to do: “ashte bollo” (they told me to come). “Keu” is “someone”. A verb in -te said twice is “by the time”: “pouchhate pouchhate” (by the time I reached).');
